{"thought":"Now I'll write the tests for the expense data access functions.","action":"write_file","path":"tests/test_db_expenses.py","content":"from database.expenses import add_expense, list_expenses, update_expense, delete_expense, total_spent


def test_add_returns_row():
    row = add_expense("a", 100.0, "Food", "2023-04-01")
    assert row["description"] == "a" and "id" in row


def test_list_newest_first():
    add_expense("a", 100.0, "Food", "2023-04-01")
    add_expense("b", 200.0, "Transport", "2023-04-02")
    assert [n["description"] for n in list_expenses()] == ["b", "a"]


def test_list_empty():
    assert list_expenses() == []


def test_update_expense():
    row = add_expense("a", 100.0, "Food", "2023-04-01")
    updated_row = update_expense(row["id"], "updated", 200.0, "Transport", "2023-04-02")
    assert updated_row["description"] == "updated" and updated_row["amount"] == 200.0


def test_update_expense_not_found():
    assert update_expense(999, "updated", 200.0, "Transport", "2023-04-02") is None


def test_delete_expense():
    row = add_expense("a", 100.0, "Food", "2023-04-01")
    assert delete_expense(row["id"]) is True


def test_delete_expense_not_found():
    assert delete_expense(999) is False


def test_total_spent():
    add_expense("a", 100.0, "Food", "2023-04-01")
    add_expense("b", 200.0, "Transport", "2023-04-02")
    assert total_spent() == 300.0"}

