async function remove(id) {
  await fetch("/api/expenses/" + id, { method: "DELETE" });
  UI.toast("Removed", "success");
  await load();
}

async function save(id, values) {
  const res = await fetch("/api/expenses/" + id, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(values),
  });
  if (!res.ok) {
    const data = await res.json();
    UI.toast(data.detail || "Could not save", "error");
    return false;
  }
  UI.toast("Saved", "success");
  await load();
}

function fieldsOf(item) {
  return { description: item.description, amount: item.amount, category: item.category, date: item.date };
}

async function load() {
  UI.loading(list);
  const res = await fetch("/api/expenses");
  if (!res.ok) {
    const data = await res.json();
    UI.toast(data.detail || "Could not load expenses", "error");
    return;
  }
  const data = await res.json();
  let shown = data.items;
  const filter = document.getElementById("filter");
  if (filter.value !== "All") shown = shown.filter((i) => i.category === filter.value);
  document.getElementById("total").textContent = UI.money(shown.reduce((sum, i) => sum + Number(i.amount || 0), 0));
  count.textContent = shown.length + " " + "expenses";
  UI.renderList(list, shown, (item) => ({
    title: "description",
    details: ["date"],
    badges: ["category"],
    formats: {"amount": "money"},
    actions: [
      { label: "Edit", onClick: () => UI.form("Edit", FIELDS, item, (values) => save(item.id, values)) },
      { label: "Delete", kind: "danger", onClick: () => remove(item.id) },
    ],
  }), "Nothing here yet. Add the first one above.");
}

